'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Stat, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './stat.css'

/**
 * Stat: every number a player reads.
 *
 * Score, timer, lives, streak, rank, multiplier, level and XP are one component
 * with a different `kind`, not eight components. They differ in the word beside
 * the number and in which token sizes them; they do not differ in how a number
 * is rendered, counted up, or announced. Eight implementations of that would be
 * eight sets of the same bug, and the first theme to land would show it.
 *
 * It performs nothing. It does not count down, fetch, or decide when a value is
 * critical. The host owns the number and says what it means; this renders it and
 * reports nothing back.
 *
 * ## Presentation (GSUI-100)
 *
 * The design draws six game-state objects as six shapes: score as a ringed chip,
 * the timer as a filled pill that changes at two thresholds, lives as a pill of
 * dots, the streak as a pill, the round as a row of segment pills. All six were
 * built as a label above a number on the page background, so a player reading a
 * HUD could not tell the timer from the score except by the word above it.
 *
 * `presentation` is the fix, and it is a prop for the same reason `choice` has
 * one: six silhouettes is not six components. The engine — the number, the
 * count, the accessible name, every state and every attribute — is identical in
 * all five, and only the container changes. `dots` and `pips` additionally draw
 * a row of marks, derived from the same `value` and `max` the number already
 * carries, so nothing is a second place the number is written down.
 *
 * `plain` is the default and is what every stat rendered before this existed, so
 * a host that has never heard of the prop sees no change.
 */

export type StatKind =
  | 'score'
  | 'timer'
  | 'lives'
  | 'streak'
  | 'round'
  | 'status'
  | 'rank'
  | 'multiplier'
  | 'level'
  | 'xp'

/**
 * The silhouette, never the meaning.
 *
 * `plain` is a label above a number, on whatever is behind it. `chip` rings it.
 * `pill` fills it. `dots` and `pips` add a row of marks to the pill, one per
 * unit of `max`: `dots` for a resource that is spent and can come back, `pips`
 * for a position in a sequence.
 */
export type StatPresentation = 'plain' | 'chip' | 'pill' | 'dots' | 'pips'

export type StatSettlement = 'optimistic' | 'settled' | 'corrected'

/**
 * What one mark stands for, per presentation.
 *
 * `dots` splits at the value: the first `value` marks are still held and the
 * rest are spent. The spent one is drawn as a dashed outline rather than a
 * different fill, because the design's dashed slot is what says "this can come
 * back" — which is the thing a broken heart said the opposite of.
 *
 * `pips` splits at the value too, but the value is a 1-based position rather
 * than a count, so the mark at `value` is the one the player is on.
 */
function markStates(presentation: StatPresentation, value: number, max: number): string[] {
  const total = Math.max(0, Math.floor(max))
  // Clamped for the drawing only. `data-gs-value` keeps whatever the host said:
  // a host passing 4 of 3 has a bug, and the attribute is where it should show.
  const held = Math.max(0, Math.min(Math.floor(value), total))
  if (presentation === 'dots') {
    return Array.from({ length: total }, (_, i) => (i < held ? 'held' : 'spent'))
  }
  return Array.from({ length: total }, (_, i) =>
    i < held - 1 ? 'done' : i === held - 1 ? 'current' : 'coming',
  )
}

export interface StatProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which number this is. Picks the word and the token scale, nothing else. */
  kind: StatKind
  /** The settled value. Always the truth, even mid count-up. */
  value: number
  /** The ceiling, for a bounded value: lives out of three, step two of five. */
  max?: number
  /** The floor, when it is not zero. */
  min?: number
  /** How much it just moved, signed. Renders as a change beside the number. */
  delta?: number
  /**
   * Whether the host has confirmed this number. Absent means it was never in
   * doubt. `optimistic` is a local render the host has yet to reconcile, and
   * `corrected` is the host disagreeing with what the player already saw.
   */
  settlement?: StatSettlement
  /** Time or resource nearly gone. The host decides where that line is. */
  critical?: boolean
  /**
   * Time or resource going, but not nearly gone: the step before `critical`.
   * The host decides where that line is too. Setting both is allowed and
   * critical wins the drawing, the way `disabled` wins over `locked`.
   */
  warning?: boolean
  /** The silhouette. Does not change what the number means or how it is announced. */
  presentation?: StatPresentation
  /** Which way it travels on its own. A timer needs it; one sample cannot say. */
  direction?: 'up' | 'down'
  /** Stopped, not finished. */
  paused?: boolean
  /** Reached the end of its range: a quest done, a timer run out. */
  complete?: boolean
  /** The word beside the number. Defaults to the kind. */
  label?: string
  /** Render the value as something other than the bare number, e.g. `1:30`. */
  format?: (value: number) => string
  /**
   * What to show on screen when it differs from what should be announced. A
   * count-up passes the number mid-flight here; `value` stays the settled one,
   * so the accessible name never reads a number the player is not keeping.
   * Without this a wrapper has to build a second root and mirror the name,
   * which is how a second state vocabulary gets born.
   */
  display?: string
  /**
   * The registry item name a wrapper wants on the root. `score`, `timer`,
   * `lives` and `streak` are their own components to a host and to a test, and
   * a HUD carrying three of these needs to tell them apart, so a wrapper says
   * which one it is rather than every one of them reading `stat`.
   */
  component?: string
}

/**
 * The words that go with the states, from the attribute contract. They live
 * here so that score, timer, lives and streak cannot ship four vocabularies for
 * the same three states.
 */
const STATE_WORD = {
  critical: 'running out',
  warning: 'going',
  paused: 'paused',
  corrected: 'updated',
  complete: 'complete',
} as const

/**
 * Which motion a change earns, by kind and direction. From the drawing's own
 * notes beside each object: `motion.pop` on the score chip and the streak
 * (3b, 3i), `motion.shake` on a life lost (4c), `motion.reveal` on a level up
 * (3i). A timer changes every second and a round changes by the host's hand,
 * so neither is an event and neither moves. Rank is the one number where down
 * is good: third to first is a gain, so a smaller rank pops.
 *
 * The value that changed carries the motion, except a life lost, which shakes
 * the whole pill: the drawing shakes the object, and a dot cannot shake on its
 * own without saying which dot went.
 */
type StatMotion = 'pop' | 'shake' | 'reveal'

const MOTION_ON_CHANGE: Partial<Record<StatKind, { up?: StatMotion; down?: StatMotion }>> = {
  score: { up: 'pop' },
  streak: { up: 'pop' },
  multiplier: { up: 'pop' },
  xp: { up: 'pop' },
  level: { up: 'reveal' },
  rank: { down: 'pop' },
  lives: { down: 'shake' },
}

/**
 * The motion the last change earned, and a counter that replays it.
 *
 * A capability plays on mount (motion.css), so replaying one is remounting the
 * element that carries it, and the counter is that element's `key`. The
 * previous value is kept in state and compared during render, the pattern
 * React documents for deriving from a prop change, so the motion lands in the
 * same commit as the new number rather than one commit later. First render
 * earns nothing: a stat arriving on screen is not a change.
 */
function useMotionOnChange(kind: StatKind, value: number) {
  const [previous, setPrevious] = React.useState(value)
  const [motion, setMotion] = React.useState<{ name: StatMotion; replay: number } | null>(null)
  if (value !== previous) {
    setPrevious(value)
    const table = MOTION_ON_CHANGE[kind]
    const name = value > previous ? table?.up : table?.down
    if (name) setMotion((last) => ({ name, replay: (last?.replay ?? 0) + 1 }))
  }
  return motion
}

export function Stat({
  kind,
  value,
  max,
  min,
  delta,
  settlement,
  critical = false,
  warning = false,
  presentation = 'plain',
  direction,
  paused = false,
  label,
  format,
  display,
  component = 'stat',
  complete = false,
  className,
  ...rest
}: StatProps) {
  // What is announced is always the settled value. What is rendered may be
  // mid-animation. Keeping them separate is the whole reason `display` exists.
  const announced = format ? format(value) : String(value)
  const rendered = display ?? announced

  // The name carries the state, because a screen reader user gets no colour, no
  // glyph and no motion. Order matters: what it is, then the number, then what
  // is true about it.
  const words = [label ?? kind, max === undefined ? announced : `${announced} of ${max}`]
  // Critical is the stronger claim, so a stat that is both says the stronger
  // word once rather than both words in a row.
  if (critical) words.push(STATE_WORD.critical)
  else if (warning) words.push(STATE_WORD.warning)
  if (paused) words.push(STATE_WORD.paused)
  if (complete) words.push(STATE_WORD.complete)
  if (settlement === 'corrected') words.push(STATE_WORD.corrected)

  // Marks are a drawing of `value` against `max`, so there is nothing to draw
  // without a `max`. A marked presentation with no ceiling degrades to the
  // number rather than throwing or rendering an empty row: a host that has not
  // said how many lives there are has a bug in its props, not in its game.
  const marks =
    (presentation === 'dots' || presentation === 'pips') && max !== undefined
      ? markStates(presentation, value, max)
      : []

  const motion = useMotionOnChange(kind, value)
  // The shake is the whole object's; everything else is the number's. Keying
  // the root remounts its DOM and nothing else: this component's own state,
  // the motion included, lives above the element and survives.
  const rootMotion = motion?.name === 'shake' ? motion : null
  const valueMotion = motion && motion.name !== 'shake' ? motion : null

  return (
    <div
      {...rest}
      key={rootMotion?.replay}
      className={['gs-stat', className].filter(Boolean).join(' ')}
      data-gs-motion={rootMotion?.name}
      data-gs-animates={rootMotion ? 'motion' : undefined}
      data-gs-component={component}
      data-gs-stat={kind}
      data-gs-presentation={presentation}
      data-gs-value={value}
      data-gs-max={max}
      data-gs-min={min}
      data-gs-delta={delta}
      data-gs-settlement={settlement}
      data-gs-critical={critical ? 'true' : undefined}
      data-gs-warning={warning ? 'true' : undefined}
      data-gs-direction={direction}
      data-gs-paused={paused ? 'true' : undefined}
      data-gs-complete={complete ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      <span className="gs-stat__label" data-gs-scope="stat" data-gs-part="label" aria-hidden="true">
        {label ?? kind}
      </span>
      {/* aria-hidden throughout: the group's label above is the accessible name,
          and announcing the pieces again would read the number twice. */}
      {/* The number pops (or, for a level, reveals) when it changes for the
          better. The key is what replays it: a new key is a new element, and a
          capability plays on mount. Motion, because it scales; the colour that
          says which way it went is on the delta's sign and survives. */}
      <span
        key={valueMotion?.replay}
        className="gs-stat__value gs-display-type"
        data-gs-scope="stat" data-gs-part="value"
        data-gs-motion={valueMotion?.name}
        data-gs-animates={valueMotion ? 'motion' : undefined}
        aria-hidden="true"
      >
        {rendered}
        {/* The marks already draw the ceiling, so "1/3" beside three dots is the
            same fact twice and the design draws neither lives nor rounds that
            way. `data-gs-max` and the accessible name still carry it. */}
        {max !== undefined && marks.length === 0 ? (
          <span className="gs-stat__max">/{max}</span>
        ) : null}
      </span>
      {marks.length ? (
        // One element for the whole row rather than one attribute per mark: the
        // number lives on the root, and a mark carrying its own state would be a
        // second place to read it from. `emphasis`, not `motion`: the marks
        // change shape and never move, which is the whole point of drawing them.
        <span
          className="gs-stat__marks"
          data-gs-scope="stat" data-gs-part="marks"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {marks.map((state, index) => (
            <span key={index} className={`gs-stat__mark gs-stat__mark--${state}`} />
          ))}
        </span>
      ) : null}
      {delta !== undefined && delta !== 0 ? (
        // The change floats up and fades over `motion.floatUp`, the drawing's
        // "+100" rising beside the score, and settles back to rest beside the
        // number. It moves, so it is motion and stops dead under reduced
        // motion. Its colour is carried by the sign in the attribute, which is
        // emphasis and survives, so a player who cannot see it move still sees
        // which way it went. Keyed on the value so the same delta twice in a
        // row (+10, +10) rises twice.
        <span
          key={`${value}:${delta}`}
          className="gs-stat__delta"
          data-gs-scope="stat" data-gs-part="delta"
          data-gs-motion="floatup"
          data-gs-animates="motion"
          aria-hidden="true"
        >
          {delta > 0 ? '+' : '−'}
          {Math.abs(delta)}
        </span>
      ) : null}
      {critical ? (
        <span
          className="gs-stat__glyph"
          data-gs-scope="stat" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          !
        </span>
      ) : null}
    </div>
  )
}

/* Stat. Every value comes from a token; nothing here is a literal colour. */

.gs-stat {
  display: inline-grid;
  grid-template-areas: 'label glyph' 'value delta';
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 0 var(--gs-space-2);
}

.gs-stat__label {
  grid-area: label;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

/* Tabular numerals, or the whole row shifts every time a digit changes and the
   number reads as jittering rather than counting. */
.gs-stat__value {
  grid-area: value;
  /* A display number sets its own leading.

     It had none, so it inherited the page's body line-height: a 36px score sa
     in a 57.6px line box, 60% taller than the glyphs, and the container grew to
     fit it. That is what made a score chip 78px tall beside 55px pills in the
     same HUD row, and it is why the shapes read as irregular before anybody
     could say why.

     1 rather than a token: these are tabular numerals with no descenders doing
     the work, and the box's own padding is what gives them room. */
  line-height: 1;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink);
  /* Colour is emphasis: it changes when the value turns critical and mus
     survive reduced motion, because it is how a player who cannot see the
     pulse still knows. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* Score is the one a player looks at from across a room, when it has the room.

   The size follows the presentation, not the word "score". A score standing on
   its own at the end of a round is the score token, 36px. The same number in a
   chip or a pill is a HUD reading, and the design draws those at the stat size:
   its own system already carries both, `stat` for a chip and `score` for the
   moment a player looks up, and we were choosing between them by the stat's
   name instead.

   It is not a preference. At 36px a score chip is 174px wide, so four chips
   need three rows at phone width and the HUD becomes a block that eats a third
   of the screen where the design has a strip across the top. The same fault pu
   a four figure score across the name beside it on the podium and truncated
   names in the leaderboard. */
.gs-stat[data-gs-stat='score'] .gs-stat__value {
  font-family: var(--gs-type-score-font-family);
  font-size: var(--gs-type-score-font-size);
  font-weight: var(--gs-type-score-font-weight);
}

.gs-stat[data-gs-stat='score']:is(
    [data-gs-presentation='chip'],
    [data-gs-presentation='pill'],
    [data-gs-presentation='dots'],
    [data-gs-presentation='pips']
  )
  .gs-stat__value {
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
}

.gs-stat__max {
  font-size: var(--gs-type-label-font-size);
  color: var(--gs-color-ink-secondary);
}

.gs-stat__delta {
  grid-area: delta;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-positive-solid);
  /* The float itself is motion.css's: the element carries
     data-gs-motion="floatup" and the shared keyframe rises it 48px over the
     float-up token. Nothing here is timed. */
}

/* The sign carries the colour, so it survives reduced motion even though the
   float does not. */
.gs-stat[data-gs-delta^='-'] .gs-stat__delta { color: var(--gs-color-negative-solid); }

.gs-stat__glyph {
  grid-area: glyph;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  color: var(--gs-color-warning);
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* Critical changes the fill, adds a glyph, and changes the accessible name.
   Never colour alone.

   It used to bump the weight to 900 as a third signal, which is a signal only
   in a theme whose display face has more than one weight. Arcade's was Bungee
   at the time, which ships one, so the browser faux-bolded it and the numerals
   smeared into each other. A signal that destroys legibility in the state where
   reading the number matters most is not a signal, and it is not needed even
   now that arcade is back on a face with real weights. The fill, the glyph and the name carry
   it, and all three work in every theme. */
.gs-stat[data-gs-critical='true'] .gs-stat__value {
  color: var(--gs-color-warning);
}

/* A paused clock is not a stopped one. It dims and keeps its place. */
.gs-stat[data-gs-paused='true'] .gs-stat__value { color: var(--gs-color-ink-secondary); }

/* An optimistic number is the player's, not yet the host's. It reads as real,
   because it is what the player will keep in almost every case; the only
   difference is that it has not settled. */
.gs-stat[data-gs-settlement='optimistic'] .gs-stat__value { opacity: 0.85; }

/* A correction is worth noticing, so it is emphasis rather than a silent swap. */
.gs-stat[data-gs-settlement='corrected'] .gs-stat__value {
  color: var(--gs-color-warning);
}

/* -- the silhouettes (GSUI-100) ------------------------------------------- */
/* Container and marks, and nothing else. Not one rule below changes the number,
   its name or any state: those are identical in all five presentations, which is
   why this is a prop rather than five components. stat.tsx has the reasoning.

   Specimen 3b draws every one of these and design/twins/3b.json measures ours
   against it, declaration by declaration. Where a rule below names a value, the
   drawing draws that value; where it names a token, the token was derived from
   the drawing. */

/* Everything but `plain` is a container, so they share the box.

   One height for every container, so a row of them is a row: the drawing stands
   the score chip, the three timers, the lives pill and the lit streak all at
   52px, which is size.chip. They used to take size.actionLarge, 68px in arcade,
   which is a button's height and made a HUD row of pills as tall as the GO
   button underneath it. The number keeps its size; the box does not take its
   size from the number. */
.gs-stat[data-gs-presentation='chip'],
.gs-stat[data-gs-presentation='pill'],
.gs-stat[data-gs-presentation='dots'],
.gs-stat[data-gs-presentation='pips'] {
  min-height: var(--gs-size-chip);
  box-sizing: border-box;
  padding: 0 var(--gs-space-4);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid transparent;
  /* Emphasis: fill and stroke are the timer's thresholds, and a threshold a
     player only sees if they can see animation is not a threshold. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    border-color var(--gs-motion-emphasis) ease-out;
}

/* No display shadow on a contained number, and the face's own leading rather
   than the tight 1 the plain stat uses: the container's height comes from
   size.chip and centres its contents, so the number no longer has to set the
   box.

   arcade sets type.displayShadow to a 3px offset, which is right under a 48px
   headline and wrong under a 22px stat: at that size the shadow sits inside the
   glyphs and "1240" reads double-struck. The drawing draws no shadow on any
   number in a chip or a pill. */
.gs-stat[data-gs-presentation='chip'] .gs-stat__value,
.gs-stat[data-gs-presentation='pill'] .gs-stat__value,
.gs-stat[data-gs-presentation='dots'] .gs-stat__value,
.gs-stat[data-gs-presentation='pips'] .gs-stat__value {
  line-height: normal;
  text-shadow: none;
}

/* A chip is a hole punched in the surface, not a plate laid on it.

   Specimen 3b draws this exact chip: a 52px pill filled with colour.edge, the
   dark, ringed at the 3px control stroke in edgeHigh, the contents centred on
   one line with the drawing's 10px gap, and floating on depth.floating. Dark
   fill and bright ring is the whole idea: it is why the score reads at a glance
   over a scene the library does not own.

   The label keeps ink-secondary, which is what the drawing sets (var(--ink2)).
   An earlier fix made it white on a bad measurement. */
.gs-stat[data-gs-presentation='chip'] {
  align-items: center;
  gap: var(--gs-space-gap);
  border-color: var(--gs-color-edge-high);
  border-width: var(--gs-stroke-control, var(--gs-stroke-ui));
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
  box-shadow: var(--gs-depth-floating);
}

/* A pill is the surface itself, outlined in colour.edge at the 3px stroke, and
   it is round: the drawing's streak is a 999px pill. The timer below squares it
   to radius.control, because that is what the drawing draws for the timer and
   only the timer. */
.gs-stat[data-gs-presentation='pill'] {
  position: relative;
  border-color: var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-surface);
}

/* The lives pill is the score chip's box without its shadow: colour.edge
   filled, ringed in edgeHigh, padded at space.inset, the dots 8px apart. The
   drawing draws the two side by side in the same HUD and they share the dark
   hole; only the score floats. */
.gs-stat[data-gs-presentation='dots'] {
  position: relative;
  padding: 0 var(--gs-space-inset);
  border-color: var(--gs-color-edge-high);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge);
}

/* The round row has no box at all. The drawing lays the pips on the scene with
   the words ROUND 3 after them, in label type: the pips carry the position and
   the text names it. It used to be a filled pill with the number at stat size
   in front of the marks, which is a second HUD chip where the drawing has a
   strip. */
.gs-stat[data-gs-presentation='pips'] {
  min-height: 0;
  padding: 0;
  border: 0;
  background: none;
}

/* One row, not three.

   The marks used to sit under the number with the label above it, which is
   three stacked rows and forces the pill into a circle: lives and round both
   came out as discs with the content crammed into a corner and two thirds of
   the shape empty. The design draws a wide pill holding the marks.

   Dots: the marks alone. The drawing's lives pill holds three dots and no
   number, because three dots with one dashed already say "2 of 3". The number
   and the label stay in the accessible name, so a screen reader still hears
   "Lives, 2 of 3": hidden from the eye, not removed. */
.gs-stat[data-gs-presentation='dots'] {
  grid-template-areas: 'marks delta glyph';
  grid-template-columns: auto auto auto;
  align-items: center;
  justify-items: start;
  gap: var(--gs-space-2);
}

/* Pips: the marks first, then the label and the number as one phrase, ROUND 3,
   both in label type. The label's own margin is the drawing's margin-left: 8px
   on the row's 8px gap, so the words sit 16px clear of the last pip. */
.gs-stat[data-gs-presentation='pips'] {
  grid-template-areas: 'marks label value delta glyph';
  grid-template-columns: auto auto auto auto auto;
  align-items: center;
  justify-items: start;
  gap: var(--gs-space-2);
}

.gs-stat[data-gs-presentation='pips'] .gs-stat__label {
  margin-inline-start: var(--gs-space-2);
}

/* ROUND and 3 are one phrase, a word space apart. The row's gap is the 8px the
   drawing draws between the pips, and a word space at 12px is nearer 4px, so
   the number gives half the gap back rather than the row losing it. */
.gs-stat[data-gs-presentation='pips'] .gs-stat__value {
  margin-inline-start: calc(var(--gs-space-1) - var(--gs-space-2));
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink-secondary);
}

/* -- the timer's three thresholds ----------------------------------------- */
/* Running, going, running out: a solid fill, then an outline, then a solid fill
   in another hue with the `!` beside it. Three shapes before three colours, so a
   player who cannot tell the hues apart still gets three answers.

   The drawing squares the timer to radius.control, 16px, where every other
   HUD element is a 999px pill: a clock face is a different shape from a score.
   Blue while it is running, gold only at the warning threshold, red only at
   critical. It used to take `interactive`, which arcade defines as the orange
   gradient, so a timer with three minutes left looked exactly like the design's
   warning state, and painting the calm state in the alarm colour teaches a
   player the wrong thing. */
.gs-stat[data-gs-presentation='pill'][data-gs-stat='timer'] {
  border-radius: var(--gs-radius-control);
}

/* A pill is one row, and its label is heard rather than seen.

   The design draws a pill holding the thing itself: the time, the streak, the
   row of life marks. It never puts the word "TIMER" or "STREAK" inside. Ours
   stacked the label above the value, which is two rows, which forces the pill
   into a circle: timer, streak, lives and round all came out as discs with the
   content crammed into one corner.

   The label stays in the accessible name, so a screen reader still hears
   "Streak, 4". Hidden from the eye, not removed. */
.gs-stat[data-gs-presentation='pill'] {
  grid-template-areas: 'value marks delta glyph';
  grid-template-columns: auto auto auto auto;
  align-items: center;
  justify-items: start;
  gap: var(--gs-space-2);
}

/* A chip keeps its label, beside the number rather than above it: the design
   draws "SCORE 12,450" on one line inside an outlined chip. */
.gs-stat[data-gs-presentation='chip'] {
  grid-template-areas: 'label value delta glyph';
  grid-template-columns: auto auto auto auto;
  align-items: center;
  gap: var(--gs-space-gap);
}

/* Heard, not seen: the pill's and the dots' label, and the dots' number. */
.gs-stat[data-gs-presentation='pill'] .gs-stat__label,
.gs-stat[data-gs-presentation='dots'] .gs-stat__label,
.gs-stat[data-gs-presentation='dots'] .gs-stat__value {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Going: the same surface, the stroke and the numerals turned to the warning
   colour. The drawing changes the outline and the ink and nothing else. */
.gs-stat[data-gs-presentation='pill'][data-gs-warning='true'] {
  border-color: var(--gs-color-warning);
}

.gs-stat[data-gs-presentation='pill'][data-gs-warning='true'] .gs-stat__value {
  color: var(--gs-color-warning);
}

/* Running out. After warning in the file, so the stronger claim wins when a
   host sets both. The fill turns to the negative colour, the outline goes back
   to colour.edge, and the numerals are white: colour.ink, which is the same
   white the running timer draws them in. The drawing writes plain white here, and
   on-bright, the dark ink for a bright fill, was drawing near-black numerals on
   a red pill where the drawing has white ones. */
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] {
  border-color: var(--gs-color-edge);
  background: var(--gs-color-negative);
  color: var(--gs-color-ink);
}

/* On a filled pill the ink comes from the fill, not the page. */
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__value,
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__label,
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__glyph {
  color: inherit;
}

/* -- the marks ------------------------------------------------------------ */
.gs-stat__marks {
  grid-area: marks;
  display: inline-flex;
  align-items: center;
  /* 8px between marks in both the lives pill and the round row. */
  gap: var(--gs-space-2);
  /* Emphasis: the marks change shape and never move, so they survive reduced
     motion, which is the whole point of drawing them. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-stat__mark {
  display: block;
  box-sizing: border-box;
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
}

/* Dots: a resource that is spent and can come back. Held is a disc of the
   negative colour ringed in colour.edge, the drawing's life; spent is the same
   circle left empty and dashed in muted, which is what says it can come back. A
   broken heart said the opposite, which is why the drawing changed. Fill and
   stroke style both differ, so nothing here depends on the colour.

   size.iconControl, 24px, for the drawing's 22px dot: the 2px is not worth a
   token. */
.gs-stat[data-gs-presentation='dots'] .gs-stat__mark {
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
}

.gs-stat__mark--held  { background: var(--gs-color-negative); }
.gs-stat__mark--spent {
  background: none;
  border-style: dashed;
  border-color: var(--gs-color-muted);
}

/* Pips: a position in a sequence. Done is a positive pill outlined in edge,
   current is wider and taller in the reward colour, coming is a bare edge-
   coloured pill with no outline. Two sizes and two fills, before any colour.

   The drawing draws a done pip 28 by 12, and 28 is no token: space.6 is 24 and
   space.8 is 32. Ours is 24 until a token lands (a request in the twin file).
   The current pip is 40 by 16, which size.controlSmall and space.4 carry. */
.gs-stat[data-gs-presentation='pips'] .gs-stat__mark {
  width: var(--gs-space-6);
  height: var(--gs-space-3);
  border-radius: var(--gs-radius-full);
}

.gs-stat__mark--done    { background: var(--gs-color-positive); }
/* Scoped like the rule above it, or that rule's width wins and the current pip
   is the same size as a done one, which is what it silently was. */
.gs-stat[data-gs-presentation='pips'] .gs-stat__mark--current {
  width: var(--gs-size-control-small);
  height: var(--gs-space-4);
  background: var(--gs-color-reward);
}
.gs-stat__mark--coming  { border: 0; background: var(--gs-color-edge); }

/* Down to the last of them. The held dots take the warning colour, so nothing
   needs a second attribute. Last, so it wins over the dots' own fill. */
.gs-stat[data-gs-critical='true'] .gs-stat__mark--held { background: var(--gs-color-warning); }
